export function countWords(s) {
  // Trim removes leading/trailing whitespace.
  // Split on any whitespace (spaces, tabs, newlines) with a regex.
  // Filter out empty strings that can appear from consecutive whitespace.
  const parts = s.trim().split(/\s+/);
  // If the trimmed string is empty, parts will be [''] -> treat as 0.
  return parts[0] === '' ? 0 : parts.length;
}
