Here’s a working version:

```js
function debounceLatest(fn, ms) {
  let timer = null;

  const wrapper = function (...args) {
    // clear any pending call
    if (timer) clearTimeout(timer);

    // schedule the latest call
    timer = setTimeout(() => {
      timer = null;           // clean up
      fn(...args);
    }, ms);
  };

  // expose a cancel method
  wrapper.cancel = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  };

  return wrapper;
}
```

What changed:  
[NOT VERIFIED] * `setTimeout` now receives a function, not the result of `fn(...a)`. * The timer reference is cleared after the call so repeated cancellations work.  
* `cancel()` clears any pending timeout and resets the timer variable. Anything marked [NOT VERIFIED] is a file, link, code quote or job I could not confirm in the repository.

Here’s a fix that checks the range and rejects leading zeros:

```js
function isIPv4(s) {
  // split into the four octets
  const parts = s.split('.');
  if (parts.length !== 4) return false;

  for (const p of parts) {
    // must be 1‑3 digits
    if (!/^\d{1,3}$/.test(p)) return false;

    // reject leading zeroes unless the part is exactly "0"
    if (p.length > 1 && p[0] === '0') return false;

    const n = Number(p);
    // each octet must be between 0 and 255
    if (n < 0 || n > 255) return false;
  }
  return true;
}
```

The function now returns true only for strings like `192.168.0.1` and rejects `999.1.1.1`, `01.2.3.4`, or any other malformed address.

```javascript
function chunk(array, size) {
  // Validate size
  if (!Number.isInteger(size) || size <= 0) {
    throw new RangeError('size must be a positive integer');
  }

  // Empty input returns empty array
  if (!Array.isArray(array) || array.length === 0) {
    return [];
  }

  const result = [];
  for (let i = 0; i < array.length; i += size) {
    // Slice creates a new sub‑array; never mutates the original
    result.push(array.slice(i, i + size));
  }
  return result;
}
```

```javascript
function parseDuration(text) {
  if (!text) return null; // empty or falsy

  // Normalize case and ensure no spaces
  const normalized = text.replace(/\s+/g, '').toUpperCase();

  // Regex to capture optional hour, minute, second parts in correct order
  const regex = /^
    (?:(\d+)H)?      # optional hours
    (?:(\d+)M)?      # optional minutes
    (?:(\d+)S)?      # optional seconds
  $/x;

  const match = normalized.match(regex);
  if (!match) return null;

  const [, h, m, s] = match;

  // Reject repeated units or out‑of‑order (regex already enforces order)
  // Ensure that if a unit appears, its number is present (regex guarantees this)
  const hours   = h ? parseInt(h, 10) : 0;
  const minutes = m ? parseInt(m, 10) : 0;
  const seconds = s ? parseInt(s, 10) : 0;

  // All numbers must be whole numbers (regex only captures digits)
  return hours * 3600 + minutes * 60 + seconds;
}
```

[NOT VERIFIED] ```javascript
class LRUCache {
  constructor(capacity) {
    if (capacity < 1) throw new RangeError('Capacity must be at least 1');
    this.capacity = capacity;
    this.map = new Map(); // preserves insertion order
  }

  // Retrieve value and mark as recently used
  get(key) {
    if (!this.map.has(key)) return -1;
    const value = this.map.get(key);
    // refresh order: delete then set
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  // Insert or update value and mark as recently used
  put(key, value) {
    if (this.map.has(key)) {
      // update existing entry
      this.map.delete(key);
    } else if (this.map.size === this.capacity) {
      // evict least recently used (first item in Map)
      const lruKey = this.map.keys().next().value;
      this.map.delete(lruKey);
    }
    this.map.set(key, value);
  }
}
