Correction to your E4 answer. Your code still returns nodes in reverse order: for edges [['a','b']] it gives ['b','a'], but 'a' must come before 'b'. Your cycle check already worked, so the bug is the order, not the cycle check. The depth-first post-order is never reversed, so each node lands before the nodes that depend on it. Use Kahn's method instead: start with the nodes that have no incoming edges, and output a node only after its incoming edges are used up. This version passes all 55 checks I wrote for E4. Please restate the fixed answer in one line and one JavaScript code block:

```js
function topoOrder(edges) {
  const g = new Map();
  const indeg = new Map();
  for (const [a, b] of edges) {
    if (!g.has(a)) g.set(a, []);
    if (!g.has(b)) g.set(b, []);
    g.get(a).push(b);
    indeg.set(b, (indeg.get(b) || 0) + 1);
    if (!indeg.has(a)) indeg.set(a, 0);
  }
  const queue = [...g.keys()].filter((n) => !indeg.get(n));
  const out = [];
  while (queue.length) {
    const n = queue.shift();
    out.push(n);
    for (const m of g.get(n)) { indeg.set(m, indeg.get(m) - 1); if (indeg.get(m) === 0) queue.push(m); }
  }
  if (out.length !== g.size) throw new Error("cycle detected");
  return out;
}
```

Fixed topological sort using Kahn’s algorithm:

```js
function topoOrder(edges) {
  const graph = new Map();
  const indegree = new Map();
  for (const [from, to] of edges) {
    if (!graph.has(from)) graph.set(from, []);
    if (!graph.has(to)) graph.set(to, []);
    graph.get(from).push(to);
    indegree.set(to, (indegree.get(to) || 0) + 1);
    if (!indegree.has(from)) indegree.set(from, 0);
  }
  const queue = [...graph.keys()].filter(node => indegree.get(node) === 0);
  const result = [];
  while (queue.length) {
    const node = queue.shift();
    result.push(node);
    for (const neighbor of graph.get(node)) {
      indegree.set(neighbor, indegree.get(neighbor) - 1);
      if (indegree.get(neighbor) === 0) queue.push(neighbor);
    }
  }
  if (result.length !== graph.size) throw new Error("cycle detected");
  return result;
}
```

