```javascript
export function parseCsv(text) {
  const lines = text.split(/\r?\n/);
  const result = [];
  let currentRow = [];
  let inQuote = false;
  let currentField = '';
  for (const line of lines) {
    let i = 0;
    while (i < line.length) {
      const char = line[i];
      if (char === '"') {
        inQuote = !inQuote;
        currentField += char;
        i++;
      } else if (char === ',' && !inQuote) {
        currentRow.push(currentField);
        currentField = '';
        i++;
      } else if (char === '\r' && i + 1 < line.length && line[i + 1] === '\n') {
        i += 1;
      } else {
        currentField += char;
        i++;
      }
    }
    if (inQuote) {
      throw new Error('Unclosed quote');
    }
    currentRow.push(currentField);
    if (currentRow.length > 0 || lines.indexOf(line) === lines.length - 1) {
      result.push(currentRow);
      currentRow = [];
    }
  }
  return result;
}
```

