export function parseDuration(text) {
  const parts = text.replace(/ /g, '').split(/(?=[dshm])/);
  const result = { d: 0, h: 0, m: 0, s: 0 };
  for (const part of parts) {
    const match = part.match(/^(\d+(?:\.\d+)?)([dshm])$/);
    if (!match) {
      throw new Error(`Invalid duration: ${text}`);
