    if (!tokens) {
        throw new SyntaxError('Invalid input');
    }

    const precedence = {
        '^': 3,
        '*': 2,
        '/': 2,
        '+': 1,
        '-': 1
    };

    const outputQueue = [];
    const operatorStack = [];

    for (const token of tokens) {
        if (!isNaN(parseFloat(token))) {
            outputQueue.push(parseFloat(token));
        } else if (token in precedence) {
            while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] in precedence && precedence[operatorStack[operatorStack.length - 1]] >= precedence[token]) {
                outputQueue.push(operatorStack.pop());
            }
            operatorStack.push(token);
        } else if (token === '(') {
            operatorStack.push(token);
        } else if (token === ')') {
            while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== '(') {
                outputQueue.push(operatorStack.pop());
            }
            if (operatorStack.length === 0 || operatorStack[operatorStack.length - 1] !== '(') {
                throw new SyntaxError('Unbalanced parentheses');
            }
            operatorStack.pop();
        } else {
            throw new SyntaxError('Invalid token');
        }
    }

    while (operatorStack.length > 0) {
        outputQueue.push(operatorStack.pop());
    }

    let result = outputQueue[0];
    for (let i = 1; i < outputQueue.length; i += 2) {
        const operator = outputQueue[i];
        const operand = outputQueue[i + 1];
        switch (operator) {
            case '^':
                result = Math.pow(result, operand);
                break;
            case '*':
                result *= operand;
                break;
            case '/':
                if (operand === 0) {
                    throw new RangeError('Division by zero');
                }
                result /= operand;
                break;
            case '+':
                result += operand;
                break;
