        currentToken = '';
      }
    } else if (char === '(' || char === ')') {
      if (currentToken !== '') {
        tokens.push(currentToken);
        currentToken = '';
      }
      tokens.push(char);
    } else if (char === '+' || char === '-' || char === '*' || char === '/' || char === '^') {
      if (currentToken !== '') {
        tokens.push(currentToken);
        currentToken = '';
      }
      tokens.push(char);
    } else if (char === '-' && currentToken === '') {
      tokens.push(char);
    } else {
      currentToken += char;
    }
